mapper.select:
SELECT id, period, metric_version, source_type, source_label, source_file, imported_at
FROM metric_snapshot WHERE period = #{period}
ORDER BY imported_at DESC, id DESC LIMIT 1

SELECT m.* FROM business_metric m
WHERE period = #{period} AND metric_version = #{metricVersion}
ORDER BY id

SELECT m.* FROM business_metric m
INNER JOIN card_metric_binding b ON b.metric_code = m.metric_code
WHERE m.period = #{period} AND m.metric_version = #{metricVersion}
  AND b.card_id = #{cardId}
ORDER BY m.id

SELECT period, metric_version, scenario, scenario_label, inputs_json
FROM scenario_baseline
WHERE period = #{period} AND metric_version = #{metricVersion} AND scenario = #{scenario}
